-- Insert qualifying entries for race 18
-- We deliberately give driver 1 two entries with different q1 string values. Because q1 is VARCHAR, lexicographic order applies.
-- For example, the string '9.5' sorts higher than '10.0' (since '9' > '1'), so depending on which qualifying row is used in the ordering the top-5 may differ when duplicates occur.

-- For driver 1: two records (note: qualifyId must be unique)
INSERT INTO QUALIFYING (qualifyId, raceId, driverId, constructorId, number, q1) 
VALUES (1, 18, 1, 1, 44, '10.0');

INSERT INTO QUALIFYING (qualifyId, raceId, driverId, constructorId, number, q1) 
VALUES (2, 18, 1, 1, 44, '9.5');

-- For the other drivers, a single record each
INSERT INTO QUALIFYING (qualifyId, raceId, driverId, constructorId, number, q1) 
VALUES (3, 18, 2, 1, 5, '10.0');

INSERT INTO QUALIFYING (qualifyId, raceId, driverId, constructorId, number, q1) 
VALUES (4, 18, 3, 1, 16, '9.8');

INSERT INTO QUALIFYING (qualifyId, raceId, driverId, constructorId, number, q1) 
VALUES (5, 18, 4, 1, 7, '9.7');

INSERT INTO QUALIFYING (qualifyId, raceId, driverId, constructorId, number, q1) 
VALUES (6, 18, 5, 1, 33, '9.6');

INSERT INTO QUALIFYING (qualifyId, raceId, driverId, constructorId, number, q1) 
VALUES (7, 18, 6, 1, 3, '9.4');

-- When executed, the inner join in Q1 produces one copy for each qualifying record from QUALIFYING (alias T1). Thus driver 1 appears twice and the sorted order (by T1.q1 DESC) may cause driver 1’s record with '9.5' to fall within the top five while the record with '10.0' falls later. In Q2 the join order (with DRIVERS as T1) may produce the duplicate rows in a different order when ordered by the QUALIFYING q1 (alias T2), and then the LIMIT 5 chooses a different subset of driverRefs. This small test database is a counterexample showing that the two queries can return different results.

