INSERT INTO ZIP_CODE (ZIP_CODE, TYPE, COUNTY, STATE) VALUES (10002, 'Regular', 'San Juan Municipio', 'Puerto Rico');
INSERT INTO ZIP_CODE (ZIP_CODE, TYPE, COUNTY, STATE) VALUES (10003, 'PO Box', 'Another County', 'Puerto Rico');
INSERT INTO ZIP_CODE (ZIP_CODE, TYPE, COUNTY, STATE) VALUES (10004, 'PO Box', 'San Juan Municipio', 'Another State');

-- Running Q1 or Q2 on this dataset will yield the result '10001' (only the first row), demonstrating that the outputs are the same.

