-- The following INSERTs are based on the originally provided schema. Under that schema the two queries are equivalent. 
-- However, to produce a counterexample one must assume a modification: 
-- Suppose the MEMBER table is altered to add a new column named zip_code (distinct from the column 'zip'):

-- ALTER TABLE MEMBER ADD COLUMN zip_code INT;

-- Then consider the following test data. The foreign key still forces MEMBER.zip to refer to a valid ZIP_CODE record, but the extra column MEMBER.zip_code is independent.

INSERT INTO MAJOR (major_id) VALUES ('MATH');

INSERT INTO ZIP_CODE (zip_code, city, state) VALUES (28091, 'Lincolnton', 'North Carolina');
INSERT INTO ZIP_CODE (zip_code, city, state) VALUES (28092, 'Lincolnton', 'North Carolina');

-- Insert a member whose foreign key (zip) points to 28091, so Q1 (which filters on ZIP_CODE.zip_code = 28092) would not return it.
-- But suppose the extra column (member.zip_code) is mistakenly filled with 28092. Then in a SQL system that resolves the unqualified name "zip_code" in Q2 to MEMBER.zip_code (because of a naming collision), Q2 would return this row.

INSERT INTO MEMBER (member_id, first_name, last_name, position, zip, link_to_major, zip_code) 
VALUES ('m1', 'John', 'Doe', 'Student', 28091, 'MATH', 28092);

/* Explanation of the divergence under this modified schema:
   • In Q1, the join brings in the ZIP_CODE row based on MEMBER.zip = ZIP_CODE.zip_code. Since for member m1, zip = 28091, it joins with the ZIP_CODE row for 28091. Then the condition T2.zip_code = 28092 fails, so m1 is not returned.
   • In Q2, if the unqualified reference to zip_code is (erroneously) interpreted as MEMBER.zip_code rather than ZIP_CODE.zip_code, then the condition becomes m1.zip_code = 28092, which is true, and the row is returned.
   This demonstrates a counterexample where omitting explicit qualification leads to different results. */

